  margin: 0 0 2rem;
  color: var(--text-muted);
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 1.75rem;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}

.form-field {
  margin: 0 0 1.5rem;
}

fieldset.radio-group {
  border: 0;
  margin: 0;
  padding: 0;
