function RadioOption({ name, value, label, checked, onChange, required }) {
  const id = useId();
  return (
    <label className="option" htmlFor={id}>
      <input
        id={id}
        type="radio"
        name={name}
        value={value}
        checked={checked}
        onChange={onChange}
        required={required}
      />
      <span className="option-label">{label}</span>
    </label>
  );
}

function NotificationPreferenceField({ value, onChange }) {
  const helpId = useId();
  const options = [
    { value: "email", label: "Email" },
    { value: "sms", label: "SMS" },
    { value: "push", label: "Push Notifications" },
  ];

  return (
    <div className="form-field">
      <fieldset className="radio-group" aria-describedby={helpId}>
        <legend>
          How do you prefer to receive notifications?
          <span className="required-marker" aria-hidden="true">*</span>
        </legend>
        <p id={helpId} className="field-help">
          Choose one option. Required.
        </p>
        <div className="options">
          {options.map((opt) => (
            <RadioOption
              key={opt.value}
              name="notification-preference"
              value={opt.value}
              label={opt.label}
              checked={value === opt.value}
              onChange={(e) => onChange(e.target.value)}
              required
            />
          ))}
        </div>
      </fieldset>
    </div>
  );
}

function NotificationForm() {
  const [preference, setPreference] = useState("");
  const [status, setStatus] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!preference) return;
    const labels = { email: "Email", sms: "SMS", push: "Push Notifications" };
    setStatus(`Preference saved: ${labels[preference]}.`);
