const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');
const axe = require('axe-core');
const babel = require('@babel/core');

const root = process.argv[2];
const html = fs.readFileSync(path.join(root, 'index.html'), 'utf8');
const css = fs.readFileSync(path.join(root, 'styles.css'), 'utf8');
const jsx = fs.readFileSync(path.join(root, 'app.jsx'), 'utf8');

const compiled = babel.transformSync(jsx, {
  presets: [['@babel/preset-env', { targets: { node: 'current' } }], '@babel/preset-react']
}).code;

// Strip external scripts/links and inline our css; we'll inject React in the window scope
const dom = new JSDOM(html.replace(/<script[\s\S]*?<\/script>/g,'').replace(/<link[^>]*styles\.css[^>]*>/, `<style>${css}</style>`), {
  runScripts: 'outside-only',
  pretendToBeVisual: true,
  url: 'http://localhost/'
});

const { window } = dom;
window.React = require('react');
window.ReactDOM = require('react-dom/client');
// Polyfill: app uses ReactDOM.createRoot — match
window.eval(`var React = window.React; var ReactDOM = window.ReactDOM;`);
try {
  window.eval(compiled);
} catch (e) {
  console.error('EVAL ERR', e);
  process.exit(2);
}

setTimeout(async () => {
  // inject axe
  window.eval(axe.source);
  const results = await window.axe.run(window.document, { resultTypes: ['violations','incomplete'] });
  console.log('VIOLATIONS:', results.violations.length);
  for (const v of results.violations) {
    console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
    for (const n of v.nodes) console.log('   ', n.target.join(' '), '|', n.failureSummary.replace(/\n/g,' '));
  }
  console.log('\nINCOMPLETE:', results.incomplete.length);
  for (const v of results.incomplete) {
    console.log(`- ${v.id}: ${v.help} (${v.nodes.length})`);
  }
  // Print rendered HTML for sanity
  // console.log(window.document.body.innerHTML.slice(0,1500));
}, 500);
EOF
