  .replace(/<script[\s\S]*?<\/script>/g, '')
  .replace(/<link[^>]*styles\.css[^>]*>/, `<style>${css}</style>`);

const dom = new JSDOM(baseHtml, { url: 'http://localhost/', pretendToBeVisual: true });
global.window = dom.window;
global.document = dom.window.document;
global.navigator = dom.window.navigator;

require(path.join(root, 'app.jsx'));

// Inject the captured HTML
dom.window.document.getElementById('root').innerHTML = captured;

const axe = require('axe-core');
const script = dom.window.document.createElement('script');
script.textContent = axe.source;
dom.window.document.head.appendChild(script);

(async () => {
  const results = await dom.window.axe.run(dom.window.document);
  console.log('VIOLATIONS:', results.violations.length);
  for (const v of results.violations) {
    console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
    for (const n of v.nodes) {
      console.log('   target:', n.target.join(' '));
      console.log('   ', n.failureSummary.replace(/\n/g, ' | '));
    }
  }
  console.log('\nINCOMPLETE:', results.incomplete.length);
  for (const v of results.incomplete) {
    console.log(`- ${v.id}: ${v.help} (${v.nodes.length} nodes)`);
    for (const n of v.nodes.slice(0,3)) console.log('   ', n.target.join(' '));
  }
})();
EOF
